\label{2.2.1}
    We say $u^{(0)}\in H^1(\Omega)$ is a weak solution of problem \eqref{IS} if and only if the following identity holds:
    \begin{align*}
        \underset{\Omega}{\int}\nabla u^{(0)}\nabla \phi{\,\textrm d}x&=\underset{\Omega}{\int} f\phi{\,\textrm d}x +\underset{L}{\int}p^{(0)}\phi 
          {\,\textrm d}\sigma,
    \end{align*}
    $\text{for all } \phi\in H_{DS}^1(\Omega)$ with $u^{(0)}=u_0$ on $S$.

\label{2.2.2}
   For each $k\in{\mathbb N}\cup\{0\}$, we say $u^{(2k+1)}\in H^1(\Omega)$ is a weak solution of problem \eqref{OS} if and only if the following identity holds:
    \begin{align*}
        \underset{\Omega}{\int}\nabla u^{(2k+1)}\nabla \psi{\,\textrm d}x&=\underset{\Omega}{\int} f\psi{\,\textrm d}x+\underset{S}{\int}q_0\psi{\,\textrm d}\sigma ,
    \end{align*}
    $\text{for all } \psi\in H_{DL}^1(\Omega)$ with $u^{(2k+1)}|_L=u^{(2k)}|_L$.

\label{2.2.3}
   For each $k\in{\mathbb N}\cup\{0\}$, we say $u^{(2k+2)}\in H^1(\Omega)$ is a weak solution of problem \eqref{ES} if and only if the following identity holds:
    \begin{align*}
        \underset{\Omega}{\int}\nabla u^{(2k+2)}\nabla \phi{\,\textrm d}x&=\underset{\Omega}{\int} f\phi{\,\textrm d}x +\underset{L}{\int}\frac{\partial u^{(2k+1)}}{\partial n}\phi{\,\textrm d}\sigma,
    \end{align*}
    $\text{for all }\phi\in H_{DS}^1(\Omega)$ with $u^{(2k+2)}=u_0$ on $S$.

Let $\psi\in H_{DL}^1(\Omega)$. From \eqref{odderro}, we get
\begin{align*}
    \underset{\Omega}{\int} \nabla e^{(2k+1)}\nabla\psi{\,\textrm d}x=0\hspace{1cm}\text{for all }\psi\in H_{DL}^1(\Omega)
\end{align*}
with $e^{(2k+1)}=e^{(2k)}$ on $L$.\\
Take $\psi:=e^{(2k+1)}-e^{(2k)}\in H_{DL}^1(\Omega)$.\\
Therefore, we obtain
$$\underset{\Omega}{\int} \nabla e^{(2k+1)}\nabla(e^{(2k+1)}-e^{(2k)}){\,\textrm d}x=0$$
which gives
$$\underset{\Omega}{\int} |\nabla e^{(2k+1)}|^2{\,\textrm d}x=\underset{\Omega}{\int} \nabla e^{(2k+1)}\nabla e^{(2k)}{\,\textrm d}x.$$
Applying the Cauchy-Schwarz inequality, we obtain that

    \begin{align*}
 \|\nabla e^{(2k+1)}\|_{L^2(\Omega)}^2&\leq \|\nabla e^{(2k+1)}\|_{L^2(\Omega)}\|\nabla e^{(2k)}\|_{L^2(\Omega)}.
\end{align*}
This implies that 
\begin{equation}\label{8}
    \|\nabla e^{(2k+1)}\|_{L^2(\Omega)}\leq\|\nabla e^{(2k)}\|_{L^2(\Omega)}\hspace{4mm}\text{for all }k\in {\mathbb N}\cup\{0\}.
\end{equation}
From \eqref{eve.erro}, we get
\begin{equation}\label{9}
    \underset{\Omega}{\int}\nabla e^{(2k+2)}\nabla\phi{\,\textrm d}x=\underset{L}{\int}\frac{\partial e^{(2k+1)}}{\partial n}\phi{\,\textrm d}\sigma\hspace{1cm}\text{for all }\phi\in H_{DS}^1(\Omega).
\end{equation}
Applying Green's formula, we can write
\begin{align*}
    \underset{\Omega}{\int}\nabla e^{(2k+1)}\nabla\xi{\,\textrm d}x&=\underset{\partial\Omega}{\int}\frac{\partial e^{(2k+1)}}{\partial n}\xi{\,\textrm d}\sigma \hspace{1cm}\text{for all }\xi\in H^1(\Omega)\\
    &=\underset{L}{\int}\frac{\partial e^{(2k+1)}}{\partial n}\xi{\,\textrm d}\sigma\hspace{1cm}\text{for all }\xi\in H^1(\Omega).
\end{align*}
Taking $\phi\in H_{DS}^1(\Omega)$, we get
\begin{equation}\label{10}
    \underset{\Omega}{\int}\nabla e^{(2k+1)}\nabla\phi{\,\textrm d}x=\underset{L}{\int}\frac{\partial e^{(2k+1)}}{\partial n}\phi{\,\textrm d}\sigma.
\end{equation}
Together, \eqref{9} and \eqref{10} imply that
\begin{align*}
    \underset{\Omega}{\int}\nabla e^{(2k+2)}\nabla\phi{\,\textrm d}x=\underset{\Omega}{\int}\nabla e^{(2k+1)}\nabla\phi{\,\textrm d}x.
\end{align*}
Take $\phi:=e^{(2k+2)}\in H_{DS}^1$ to yield
\begin{align*}
    \underset{\Omega}{\int}|\nabla e^{(2k+2)}|^2{\,\textrm d}x&=\underset{\Omega}{\int}\nabla e^{(2k+1)}\nabla e^{(2k+2)}{\,\textrm d}x.
\end{align*}
Applying the Cauchy-Schwarz inequality, we obtain that
    \begin{align*}
     \|\nabla e^{(2k+2)}\|_{L^2(\Omega)}^2&\leq \|\nabla e^{(2k+1)}\|_{L^2(\Omega)}\|\nabla e^{(2k+2)}\|_{L^2(\Omega)}.
\end{align*}
This implies that 
\begin{equation}\label{11}
    \|\nabla e^{(2k+2)}\|_{L^2(\Omega)}\leq\|\nabla e^{(2k+1)}\|_{L^2(\Omega)}\hspace{4mm}\text{for all }k\in {\mathbb N}\cup\{0\}.
\end{equation}
By \eqref{8} and \eqref{11} we see that
$$0\leq \cdots\cdots\leq\|\nabla e^{(k+1)}\|_{L^2(\Omega)}\leq\|\nabla e^{(k)}\|_{L^2(\Omega)}\leq\cdots\cdots\leq\|\nabla e^{(0)}\|_{L^2(\Omega)}.$$

\label{Le 3.1.2}
  Let \ref{A_1}--\ref{A_3} and \ref{B} hold. If $e^{(k)}$ satisfies \eqref{ini.erro}--\eqref{eve.erro} for every $k\in {\mathbb N}\cup \{0\}$, then 
\begin{enumerate}
      \item $\nabla e^{(k+1)}$ is orthogonal to $\nabla(e^{(k)}-e^{(k+1)})$ for all $k\in{\mathbb N}\cup \{0\}$.
      \item $\|\nabla (e^{(k)}-e^{(k+1)})\|_{L^2(\Omega)}\to 0$ as $k \to \infty$.
  \end{enumerate}

Recall that $e^{(k)}=u^{(k)}-u$ and that $e^{(k)}$ satisfies \eqref{ini.erro}--\eqref{eve.erro} $\text{for all } k\in {\mathbb N}\cup \{0\}$.\\
We work with the Hilbert space $\mathcal{H}$ and the two closed subspaces $V_D$ and $V_N$ introduced in Section \ref{sec 3.2}.\\
Let $$P_{V_N}:\mathcal{H}\to V_N$$ be the orthogonal projection onto $V_N$.\\
We claim that $$e^{(2k+1)}=P_{V_N}(e^{(2k)})\hspace{4mm}\text{for all }k\in {\mathbb N}\cup\{0\}.$$
Let $\xi\in V_N$. For all $k\in {\mathbb N}\cup\{0\}$, we can write
\begin{align*}
    \underset{\Omega}{\int}\nabla(e^{(2k)}-e^{(2k+1)})\nabla\xi{\,\textrm d}x&=\underset{\partial \Omega}{\int}(e^{(2k)}-e^{(2k+1)})\frac{\partial\xi}{\partial n}{\,\textrm d}\sigma\\
    &=\underset{L}{\int}(e^{(2k)}-e^{(2k+1)})\frac{\partial\xi}{\partial n}{\,\textrm d}\sigma\hspace{8mm} \text{for all }\xi\in V_N.
\end{align*}
Since $ e^{(2k+1)}=e^{(2k)}$ on $L$, we obtain
\begin{equation}\label{15}
    \underset{\Omega}{\int}\nabla(e^{(2k)}-e^{(2k+1)})\nabla\xi{\,\textrm d}x=0\hspace{8mm} \text{for all }\xi\in V_N.
    \end{equation}
From \eqref{odderro}, we see that $e^{(2k+1)}\in V_N$.
    By \eqref{15} and the fact that $e^{(2k+1)}\in V_N$, we get 
    \begin{equation}\label{16}
        e^{(2k+1)}=P_{V_N}(e^{(2k)})\hspace{4mm}\text{for all }k\in {\mathbb N}\cup\{0\}.
    \end{equation}
    Let $$P_{V_D}:\mathcal{H}\to V_D$$ be the orthogonal projection onto $V_D$.\\
Proceeding similarly, we claim that 
$$e^{(2k+2)}=P_{V_D}(e^{(2k+1)})\hspace{4mm}\text{for all }k\in {\mathbb N}\cup\{0\}.$$
Let $\chi\in V_D$. For all $k\in {\mathbb N}\cup\{0\}$, we can write
\begin{align*}
    \underset{\Omega}{\int}\nabla(e^{(2k+1)}-e^{(2k+2)})\nabla\chi{\,\textrm d}x&=\underset{\partial \Omega}{\int}\frac{\partial}{\partial n}(e^{(2k+1)}-e^{(2k+2)})\chi{\,\textrm d}\sigma\\
    &=\underset{L}{\int}\frac{\partial}{\partial n}(e^{(2k+1)}-e^{(2k+2)})\chi{\,\textrm d}\sigma\hspace{8mm} \text{for all }\chi\in V_D.
\end{align*}
Since $\frac{\partial e^{(2k+2)}}{\partial n}=\frac{\partial e^{(2k+1)}}{\partial n}$ on $L$, we obtain
\begin{equation}
    \begin{aligned}\label{17}
    \underset{\Omega}{\int}\nabla(e^{(2k+1)}-e^{(2k+2)})\nabla\chi{\,\textrm d}x&=0\hspace{8mm}\text{for all }\chi\in V_D.
\end{aligned}
\end{equation}
  From  \eqref{eve.erro}, we have $e^{(2k+2)}\in V_D$. By \eqref{17} and the fact that  $e^{(2k+2)}\in V_D$,we get 
  \begin{equation}\label{18}
      e^{(2k+2)}=P_{V_D}(e^{(2k+1)})\hspace{4mm}\text{for all }k\in {\mathbb N}\cup\{0\}.
  \end{equation}
 Finally, we can combine \eqref{16} and \eqref{18} to get
\begin{align*}
  e^{(2k+2)}&=P_{V_D}\circ P_{V_N}(e^{(2k)}) \\
  &=(P_{V_D}\circ P_{V_N})^2(e^{(2k-2)})\\
  &\hspace{1cm}\vdots\\
  &= (P_{V_D}\circ P_{V_N})^{k+1}(e^{(0)}).
\end{align*}
By Proposition \ref{Pr 3.1.3}, we obtain
\begin{equation}\label{19}
    (P_{V_D}\circ P_{V_N})^{k+1}(e^{(0)})\to P_{V_D\cap V_N}(e^{(0)})\hspace{6mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation}
By \eqref{19} and \eqref{VdVnIntersect}, we deduce that
$$
    \lim_{k\rightarrow\infty}(P_{V_D}\circ P_{V_N})^{k+1}(e^{(0)})\to P_{V_D\cap V_N}(e^{(0)})=P_{\{0\}}(e^{(0)})=0
$$
in $\mathcal{H}$. Consequently, we also get
\begin{equation}\label{21}
    e^{(2k+2)}\to 0\hspace{2mm}\text{strongly in}\hspace{1mm}\mathcal{H} \hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation} 
Since $e^{(2k+1)}=P_{V_N}(e^{(2k)})$ and $e^{(2k+2)}\to 0$ strongly in $\mathcal{H}$ as $k\to\infty$, this implies that
\begin{equation}\label{22}
    e^{(2k+1)}\to 0\hspace{2mm}\text{strongly in}\hspace{1mm}\mathcal{H}\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation}
By \eqref{21} and \eqref{22}, we get
\begin{equation}\label{23}
    e^{(k)}\to 0 \hspace{2mm}\text{strongly in}\hspace{1mm}\mathcal{H}\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation}
It is not sufficient to show that $e^{(k)}\to 0$ strongly in $\mathcal{H}$ as $k\to 0$. We also need to establish that  $e^{(k)}\to 0$ strongly in $H^1(\Omega)$ as $k\to\infty$.\\
Consequently, \eqref{23} leads to $$\|\nabla e^{(k)}\|_{L^2(\Omega)}\to 0\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.$$
Since $e^{(2k+2)}=0$ on $S$,  the Poincar\'e inequality implies that 
\begin{equation}\label{24}
    e^{(2k+2)}\to 0 \hspace{3mm} \text{strongly in}\hspace{2mm} H^1(\Omega)\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation}
We denote $\Tilde{e}^{(2k+1)}:=e^{(2k+1)}-e^{(2k)}$ with $\Tilde{e}^{(2k+1)}\in H^1(\Omega)$. By \eqref{odderro}, we get
$$\underset{\Omega}{\int}\nabla(\Tilde{e}^{(2k+1)}+e^{(2k)})\nabla\psi{\,\textrm d}x=0\hspace{1cm}\text{for all } \psi\in H_{DL}^1(\Omega).$$
Taking $\psi=\Tilde{e}^{(2k+1)}\in H_{DL}^1$ in the last expression, we obtain
\begin{align*}
    \underset{\Omega}{\int}\nabla(\Tilde{e}^{(2k+1)}+e^{(2k)})\nabla\Tilde{e}^{(2k+1)}{\,\textrm d}x&=0.
    \end{align*}
    Rearranging the terms and applying the Cauchy-Schwarz inequality, we get
    \begin{align*}
    \underset{\Omega}{\int}|\nabla\Tilde{e}^{(2k+1)}|^2{\,\textrm d}x&\leq|\underset{\Omega}{\int}\nabla e^{(2k)}\nabla\Tilde{e}^{(2k+1)}|{\,\textrm d}x\\
    \|\nabla\Tilde{e}^{(2k+1)}\|_{L^2(\Omega)}^2&\leq \|\nabla e^{(2k)}\|_{L^2(\Omega)} \|\nabla\Tilde{e}^{(2k+1)}\|_{L^2(\Omega)}.
\end{align*}
This implies that
\begin{equation}\label{25}
    \|\nabla\Tilde{e}^{(2k+1)}\|_{L^2(\Omega)}\leq\|\nabla e^{(2k)}\|_{L^2(\Omega)}.
\end{equation}
Applying the Poincar\'e inequality on $\Tilde{e}^{(2k+1)}$ and combining it with \eqref{24} and \eqref{25}, we get
\begin{equation}\label{26}
    \Tilde{e}^{(2k+1)}\to 0 \hspace{3mm} \text{strongly in}\hspace{2mm} H^1(\Omega)\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation} 
By \eqref{24} and \eqref{26}, and by setting $\Tilde{e}^{(2k+1)}=e^{(2k+1)}-e^{(2k)}$,we deduce that 
\begin{equation}\label{27}
    e^{(2k+1)}\to 0 \hspace{3mm} \text{strongly in}\hspace{2mm} H^1(\Omega) \hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.
\end{equation}
By \eqref{24} and \eqref{27}, we finally see $$e^{(k)}\to 0 \hspace{2mm}\text{strongly in}\hspace{1mm}H^1(\Omega)\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty,$$
which equivalently gives $$u^{(k)}\to u\hspace{2mm}\text{strongly in}\hspace{1mm}H^1(\Omega)\hspace{7mm}\text{as}\hspace{1.5mm} k\to\infty.$$ This concludes the proof of our main result.

\label{exampleProp}
   There exists a bounded domain $\Omega\subset {\mathbbm R}^2$  such that
   $$ c(V_D,V_N)=1,$$ where $V_D$ and $V_N$ are defined as in Section \ref{sec 3.2}.

The sum $V_D+V_N$ is closed if and only if $c(V_D,V_N)<1$   (see \cite[Lemma 1.3]{Heinz}). Thus, it suffices to give an explicit example of $\Omega$ and $S$ such that the corresponding space $V_D+V_N$ is not closed. To this end, 
let $\Omega:=[0,1]\times[0,1]$, $S:=\{(x,0):0<x<1\}$, and $L:=\partial\Omega\setminus S$.
It is known (see \cite[Theorem 1.1]{Zhe}) that $V_D+V_N$ is closed if and only if there exist a constant $K>0$ such that 
    \begin{equation}\label{closedinequality}
        \|u\|_{\mathcal{H}}\leq K\|u+v\|_{\mathcal{H}}\hspace{4mm}\text{for all } u\in V_D, v\in V_N.
    \end{equation}
Assume for a contradiction that \eqref{closedinequality} holds. Consider the sequences
 $(u_n)\subset V_D$  and $(v_n)\subset V_N$  given by $u_n:=\sin{(nx)}\sinh{(ny)}$ and $v_n:=-\sin{(nx)}\cosh{(ny)}$. Then
 $$\Delta u_n=-n^2\sin{(nx)}\sinh{(ny)}+n^2\sin{(nx)}\sinh{(ny)}=0$$
 and $$\Delta v_n=n^2\sin{(nx)}\cosh{(ny)}-n^2\sin{(nx)}\cosh{(ny)}=0,$$
 whence $u_n$ and $v_n$ are harmonic. Clearly, $u_n|_{S}=0$ and 
 $$\frac{\partial v_n}{\partial n}\Big|_{S}=-\frac{\partial v_n}{\partial y}\Big|_{S}=n\sin{(nx)}\sinh{(ny)}\big|_S=0.$$
 Therefore $u_n\in V_D$ and $v_n\in V_N$.
 Note that for all $n\in\mathbb{N}$
 \begin{align*}
     \|\nabla u_n\|_{L^2(\Omega)}^2&=n^2\underset{0}{\int}^1\underset{0}{\int}^1\big(\cos^2{(nx)}\sinh^2{(ny)}+\sin^2{(nx)}\cosh^2{(ny)}\big){\,\textrm d}x{\,\textrm d}y\\
     &=\frac{n}{4}\big(\sinh{(2n)}-\sin{(2n)}\big)= \frac{n}{8} e^{2n}(1-e^{-4n}-2\sin{(2n)}e^{-2n})\\
     &\ge\frac{ne^{2n}}{16},
 \end{align*}
 and
 \begin{align*}
     \|\nabla(u_n+v_n)\|_{L^2(\Omega)}^2&=n^2\underset{0}{\int}^1\underset{0}{\int}^1\big(\sin^2(nx)+\cos^2(nx)\big) e^{-2ny}{\,\textrm d}x{\,\textrm d}y=\frac{n}{2}(1-e^{-2n})\\
     &\le\frac{n}{4}.
 \end{align*}
 Consequently,
 \begin{align}
     \nonumber
     \frac{ \|\nabla u_n\|_{L^2(\Omega)}^2}{ \|\nabla(u_n+v_n)\|_{L^2(\Omega)}^2}\ge\frac{e^{2n}}{4}.
 \end{align}
On the other hand, by \eqref{closedinequality}, there exists $K>0$ such that
\begin{align*}
    \frac{ \|\nabla u_n\|_{L^2(\Omega)}^2}{ \|\nabla(u_n+v_n)\|_{L^2(\Omega)}^2}\leq K^2.
\end{align*}
Whence,
\begin{align*}
    e^{2n}\leq 4K^2,
\end{align*}
which is a contradiction. Hence $V_D+V_N$ is not closed.

\label{formalRemark}
    Interestingly, if we allow ourselves to 
argue formally, we notice the proportionality between $c(V_D,V_N)$ and the measure of the inaccessible part of the boundary $L$.  
We let \ref{A_1} hold, and consider that $V_D$ and $V_N$  to be  the same closed subspaces of $\mathcal{H}$ defined in Section \ref{sec 3.2} and, additionally, assumes that there exists a constant $C'>0$ such that  
 \begin{equation}\label{conditionbound}
     \left\|\frac{\partial v}{\partial n}\right\|_{L^\infty(L)}\leq C'\hspace{4mm}\text{ for every } v\in V_N.
 \end{equation}
Using the Green's formula, the fact that $u=0$ on $S$, and the standard trace-Poincar\'{e} machinery, we obtain
\begin{align}
    \nonumber
    \left|\int_\Omega\nabla u\nabla v{\,\textrm d}x\right|&=\left|\int_L\frac{\partial v}{\partial n}u{\,\textrm d}\sigma\right|\le C'\int_L|u|{\,\textrm d}\sigma\le C'\sqrt{|L|}\|u\|_{L^2(\partial\Omega)}\\
    \nonumber
    &\le C'C'_\Omega\sqrt{|L|}\|\nabla u\|_{L^2(\Omega)}\le C_\Omega\sqrt{|L|}\|\nabla u\|_{L^2(\Omega)},
\end{align}
where $|L|$ denotes the surface measure of $L$. Hence,
\begin{equation}\label{conditionrate}
    c(V_D,V_N)\leq C_\Omega\sqrt{|L|}. 
\end{equation}
In \eqref{conditionrate}, $C_\Omega>0$ is a constant that depends on the set $\Omega$ (via the trace inequality and Poincar\'{e}'s inequality), as well as the bound (\ref{conditionbound}).
This estimate indicates that, should it exists, the convergence rate is affected   by the size of the unknown part of the boundary $L$. In particular, $c(V_D,V_N)$ decreases as the measure of $L$ becomes smaller. Therefore, a smaller interface measure of $L$ leads to a smaller value of $c(V_D,V_N)$, which ultimately results in faster convergence, i.e. the more we know, the faster we expect to converge\footnote{This is (somewhat trivially) a rigorous statement in the one-dimensional case. In higher space dimensions, an assumption like \eqref{conditionbound} can only hold if one is able to lift sufficiently high the regularity of the target solution (perhaps by taking solutions from $H^3(\Omega)$ instead of $H^1(\Omega)$). However, this regularity lift would change the underlying Hilbert space $\mathcal{H}$ as well as the meaning of the spaces $V_D$ and $V_N$; so, the  setting of the alternating orthogonal projections method changes drastically and a new analysis would need to be done. }.
